func (h *ExecuteHealHandler) fetchAndWriteChunked(ctx context.Context, entry *source.TableRegistry, ids []string, label string) (int, []string, error) {
	totalWritten := 0
	var healedIDs []string
	var lastErr error
	for start := 0; start < len(ids); start += segAChunkSize {
		end := start + segAChunkSize
		if end > len(ids) {
			end = len(ids)
		}
		written, accepted, err := h.FetchAndWriteByIDsWithAccepted(ctx, entry, ids[start:end])
		if err != nil {
			lastErr = err
		}
		totalWritten += written
		healedIDs = append(healedIDs, accepted...)
	}
	if totalWritten == 0 && lastErr != nil {
		return 0, nil, lastErr
	}
	return totalWritten, healedIDs, nil
}

